import { useRef, useEffect } from 'react';

const AdvancedMarker = ({ position, map, draggable, onDragEnd, onMarkerError }) => {
  const markerRef = useRef(null);

  useEffect(() => {
    if (!map || !window.google || !window.google.maps || !window.google.maps.marker) return;

    try {
      const { AdvancedMarkerElement } = window.google.maps.marker;
      if (!AdvancedMarkerElement) return;

      if (!markerRef.current) {
        markerRef.current = new AdvancedMarkerElement({
          map,
          position,
          gmpDraggable: draggable,
        });

        if (onDragEnd) {
          markerRef.current.addListener('dragend', (e) => {
            onDragEnd(e);
          });
        }
      } else {
        markerRef.current.position = position;
        markerRef.current.gmpDraggable = draggable;
      }
    } catch (error) {
      console.warn('AdvancedMarker initialization error:', error);
      if (onMarkerError) onMarkerError(error);
    }

    return () => {
      try {
        if (markerRef.current) {
          window.google.maps.event.clearInstanceListeners(markerRef.current);
          markerRef.current.map = null;
          markerRef.current = null;
        }
      } catch (error) {
        console.warn('AdvancedMarker cleanup error:', error);
      }
    };
  }, [map, position, draggable, onDragEnd, onMarkerError]);

  return null;
};

export default AdvancedMarker;