import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { createRoom, editRoom, getUploadUrl, getItemById } from '../../api/listingService';
import { toast } from "sonner";
import { useAuth } from '../../context/AuthContext';
import { useGoogleMaps, MAP_ID } from '../../context/GoogleMapsContext';
import { Autocomplete, GoogleMap } from '@react-google-maps/api';
import AdvancedMarker from '../common/AdvancedMarkerMap';
import { FaWifi, FaBolt, FaTint, FaShower, FaTshirt, FaCar, FaBed, FaLaptopHouse, FaShieldAlt, FaPlus, FaSnowflake, FaTimes, FaRupeeSign, FaBath, FaInfoCircle, FaMapPin } from 'react-icons/fa';
import { MapPin } from 'lucide-react';
import { FaKitchenSet } from 'react-icons/fa6';
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../../components/ui/select";
import { Textarea } from "../../components/ui/textarea";
import { cn } from "../../lib/utils";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "../../components/ui/dialog";



const FACILITY_OPTIONS = [
    { key: 'wifi', name: 'WiFi', icon: FaWifi },
    { key: 'electricity', name: '24/7 Electricity', icon: FaBolt },
    { key: 'mineral_water', name: 'Mineral Water', icon: FaTint },
    { key: 'hot_water', name: 'Hot/Cold Water', icon: FaShower },
    { key: 'laundry', name: 'Laundry', icon: FaTshirt },
    { key: 'ac', name: 'AC', icon: FaSnowflake },
    { key: 'parking', name: 'Parking', icon: FaCar },
    { key: 'bed', name: 'Bed', icon: FaBed },
    { key: 'study_table', name: 'Study Table', icon: FaLaptopHouse },
    { key: 'security', name: 'Security', icon: FaShieldAlt },
    { key: 'kitchen', name: 'Kitchen', icon: FaKitchenSet }
];

const CustomRadioToggle = ({ label, isActive, onClick, icon: Icon }) => (
    <div
        onClick={onClick}
        className={cn(
            "flex items-center gap-2 p-3 rounded-xl border-2 transition-all cursor-pointer shadow-md",
            isActive
                ? "border-amber-500 bg-gradient-to-r from-green-600 to-green-700 text-white scale-[1.03]"
                : "border-gray-300 bg-white text-gray-700 hover:bg-gray-50"
        )}
    >
        <div className={cn(
            "w-8 h-8 rounded-full flex items-center justify-center",
            isActive ? "bg-white" : "bg-gray-100"
        )}>
            <Icon size={18} className={isActive ? "text-green-600" : "text-gray-600"} />
        </div>
        <p className="font-bold text-lg">{label}</p>
    </div>
);

const CreateRoomForm = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const editRoomId = searchParams.get('edit');
  const isEditMode = !!editRoomId;

    // Basic States
    const [title, setTitle] = useState('');
    const [rent, setRent] = useState('');
    const [description, setDescription] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isLoadingData, setIsLoadingData] = useState(false);
    const [location, setLocation] = useState(null);
    const [address, setAddress] = useState("");
    const [mapCenter, setMapCenter] = useState({ lat: 18.5204, lng: 73.8567 });
    const [selectedFacilities, setSelectedFacilities] = useState([]);
    const [coverPhoto, setCoverPhoto] = useState(null);
    const [otherPhotos, setOtherPhotos] = useState([]);
    const searchBoxRef = useRef(null);
    const [isConfirmOpen, setIsConfirmOpen] = useState(false);

    // Navin States
    const [roomType, setRoomType] = useState('single');
    const [gender, setGender] = useState('any');
    const [lightBillIncluded, setLightBillIncluded] = useState(true);
    const [bathroom, setBathroom] = useState('attached');

    // Preview States
    const [coverPhotoPreview, setCoverPhotoPreview] = useState(null);
    const [otherPhotosPreviews, setOtherPhotosPreviews] = useState([]);

    const [existingCoverUrl, setExistingCoverUrl] = useState('');
    const [existingOtherUrls, setExistingOtherUrls] = useState([]);
    const [mapInstance, setMapInstance] = useState(null);
    const [mapError, setMapError] = useState(false);

    // Load existing room data in edit mode
    useEffect(() => {
        if (isEditMode && editRoomId) {
            const loadRoomData = async () => {
                setIsLoadingData(true);
                try {
                    const room = await getItemById('room', editRoomId);
                    if (room) {
                        setTitle(room.title || '');
                        setRent(room.rent?.toString() || '');
                        setDescription(room.description || '');
                        setAddress(room.address || '');
                        setLocation(room.location ? { lat: room.location.lat, lng: room.location.lng } : null);
                        setSelectedFacilities(room.facilities || []);
                        setRoomType(room.roomType || 'single');
                        setGender(room.gender || 'any');
                        setLightBillIncluded(room.lightBillIncluded ?? true);
                        setBathroom(room.bathroom || 'attached');
                        setExistingCoverUrl(room.cover_photo_url || '');
                        setExistingOtherUrls(room.other_photos_urls || []);
                        setCoverPhotoPreview(room.cover_photo_url || null);
                        setOtherPhotosPreviews(room.other_photos_urls || []);
                    }
                } catch (error) {
                    toast.error('Failed to load room data');
                    navigate('/owner/rooms');
                } finally {
                    setIsLoadingData(false);
                }
            };
            loadRoomData();
        }
}, [isEditMode, editRoomId, navigate]);

// Redirect unauthorized users (only block creation, not editing existing rooms)
useEffect(() => {
const serviceType = user?.serviceType;
if (serviceType === 'mess') {
toast.error('You are not authorized to create rooms. Please use your mess dashboard.');
navigate('/owner/mess');
} else if (!isEditMode && serviceType !== 'room' && serviceType !== 'both') {
toast.error('Please complete your profile to create room listings.');
navigate('/owner/rooms');
}
}, [user, isEditMode, navigate]);

// Cleanup object URLs to prevent memory leaks
    useEffect(() => {
        return () => {
            if (coverPhotoPreview && !coverPhotoPreview.startsWith('http')) {
                URL.revokeObjectURL(coverPhotoPreview);
            }
            otherPhotosPreviews.forEach(url => {
                if (!url.startsWith('http')) {
                    URL.revokeObjectURL(url);
                }
            });
        };
    }, [coverPhotoPreview, otherPhotosPreviews]);

    const { isLoaded, loadError } = useGoogleMaps();

    const handleMapLoad = (map) => {
        setMapInstance(map);
        setMapError(false);
    };

    const handleMapError = (error) => {
        console.error('Google Maps error:', error);
        setMapError(true);
    };

    const handleMarkerError = (error) => {
        console.warn('Marker error:', error);
        setMapError(true);
    };

    const handleCoverPhotoChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setCoverPhoto(file);
            setCoverPhotoPreview(URL.createObjectURL(file));
        }
    };

    const handleOtherPhotosChange = (e) => {
        const files = Array.from(e.target.files);

        // Check total photos after adding new ones
        if (otherPhotos.length + files.length > 6) {
            toast.error('You can only upload up to 6 additional photos');
            return;
        }

        setOtherPhotos(prev => [...prev, ...files]);
        const newPreviews = files.map(file => URL.createObjectURL(file));
        setOtherPhotosPreviews(prev => [...prev, ...newPreviews]);
    };

    const removeOtherPhoto = (indexToRemove) => {
        // Revoke the URL of the removed photo to prevent memory leak
        const photoToRemove = otherPhotosPreviews[indexToRemove];
        if (photoToRemove) {
            URL.revokeObjectURL(photoToRemove);
        }

        setOtherPhotos(prev => prev.filter((_, index) => index !== indexToRemove));
        setOtherPhotosPreviews(prev => prev.filter((_, index) => index !== indexToRemove));
    };

    const handleFacilityToggle = (key) => {
        setSelectedFacilities(prev =>
            prev.includes(key) ? prev.filter(f => f !== key) : [...prev, key]
        );
    };

    const handlePlaceSelect = () => {
        const place = searchBoxRef.current.getPlace();
        if (place && place.geometry) {
            const lat = place.geometry.location.lat();
            const lng = place.geometry.location.lng();
            setAddress(place.formatted_address);
            setLocation({ lat, lng });
            setMapCenter({ lat, lng });
        }
    };

    const handleMapClick = (e) => {
        const lat = e.latLng.lat();
        const lng = e.latLng.lng();
        setLocation({ lat, lng });
        setMapCenter({ lat, lng });
    };

    const handleMarkerDragEnd = (e) => {
        const lat = e.latLng.lat();
        const lng = e.latLng.lng();
        setLocation({ lat, lng });
        setMapCenter({ lat, lng });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        // In edit mode, cover photo is optional (existing photo will be used)
        if (isEditMode && !coverPhoto && !existingCoverUrl) {
            toast.error('Please select a cover photo.');
            return;
        }

        // In create mode, cover photo is required
        if (!isEditMode && !coverPhoto) {
            toast.error('Please select a cover photo.');
            return;
        }

        if (!location) {
            toast.error('Please select a location.');
            return;
        }
        if (!title || !rent) {
            toast.error('Please fill in all required fields.');
            return;
        }

        setIsConfirmOpen(true);
    };

    const handleConfirmSubmit = async () => {
        setIsLoading(true);
        setIsConfirmOpen(false);

        try {
            let finalCoverUrl = existingCoverUrl;
            let finalOtherUrls = [...existingOtherUrls];

            // Upload new cover photo if changed
            if (coverPhoto) {
                const coverToast = toast.loading('Uploading cover photo...');
                try {
                    const uploadRes = await getUploadUrl(coverPhoto.type, 'rooms');
                    const coverUploadUrl = uploadRes?.uploadUrl;
                    const newCoverUrl = uploadRes?.imageUrl || uploadRes?.finalUrl;
                    if (coverUploadUrl && !coverUploadUrl.includes('mock')) {
                        try {
                            await fetch(coverUploadUrl, {
                                method: 'PUT',
                                body: coverPhoto,
                                headers: { 'Content-Type': coverPhoto.type }
                            });
                        } catch (e) {
                            console.info("Demo Mode: Simulating cover photo upload", e);
                        }
                    }
                    finalCoverUrl = newCoverUrl || (typeof coverPhoto === 'string' ? coverPhoto : URL.createObjectURL(coverPhoto));
                } finally {
                    toast.dismiss(coverToast);
                }
            }

            // Upload new other photos
            if (otherPhotos.length > 0) {
                const otherToast = toast.loading(`Uploading ${otherPhotos.length} additional photos...`);
                try {
                    const newPhotoUrls = await Promise.all(
                        otherPhotos.map(async (photo) => {
                            const uploadRes = await getUploadUrl(photo.type, 'rooms');
                            const uploadUrl = uploadRes?.uploadUrl;
                            const imageUrl = uploadRes?.imageUrl || uploadRes?.finalUrl;
                            if (uploadUrl && !uploadUrl.includes('mock')) {
                                try {
                                    await fetch(uploadUrl, {
                                        method: 'PUT',
                                        body: photo,
                                        headers: { 'Content-Type': photo.type }
                                    });
                                } catch (e) {
                                    console.info("Demo Mode: Simulating additional photo upload", e);
                                }
                            }
                            return imageUrl || (typeof photo === 'string' ? photo : URL.createObjectURL(photo));
                        })
                    );
                    finalOtherUrls = [...existingOtherUrls, ...newPhotoUrls];
                } finally {
                    toast.dismiss(otherToast);
                }
            }

            // Prepare final data
            const roomData = {
                room_id: isEditMode ? editRoomId : undefined,
                title,
                rent: Number(rent),
                description,
                address,
                facilities: selectedFacilities,
                location: { lat: location.lat, lng: location.lng },
                cover_photo_url: finalCoverUrl,
                other_photos_urls: finalOtherUrls,
                gender,
                roomType,
                bathroom,
                lightBillIncluded
            };

            // Submit to backend
            const saveToast = toast.loading('Saving room details...');

            if (isEditMode) {
                await editRoom(roomData);
                toast.dismiss(saveToast);
                toast.success('Room updated successfully!');
            } else {
                await createRoom(roomData);
                toast.dismiss(saveToast);
                toast.success('Your room listing has been submitted for approval!');
            }

            navigate('/owner/rooms');

        } catch (error) {
            toast.dismiss();
            toast.error(error.message || `Failed to ${isEditMode ? 'update' : 'create'} room listing. Please try again.`);
            console.error("Room Error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    const clearForm = () => {
        setTitle('');
        setRent('');
        setDescription('');
        setLocation(null);
        setAddress('');
        setSelectedFacilities([]);
        setCoverPhoto(null);
        setOtherPhotos([]);
        setCoverPhotoPreview(null);
        setOtherPhotosPreviews([]);
        setRoomType('single');
        setGender('any');
        setLightBillIncluded(true);
        setBathroom('attached');
    };

    if (loadError) return <div className="text-center py-12">Error loading maps</div>;
    if (!isLoaded) return <div className="text-center py-12">Loading Maps...</div>;

    return (
        <div className="min-h-[calc(100vh-64px)] py-8 px-4 bg-[#d4c6a6]">
            {/* Loading State */}
            {isLoadingData ? (
                <div className="flex justify-center items-center min-h-[50vh]">
                    <div className="space-y-4 w-full max-w-lg">
                        <div className="h-10 w-64 bg-gray-200 rounded animate-pulse mx-auto"></div>
                        <div className="h-80 bg-gray-200 rounded-xl animate-pulse"></div>
                    </div>
                </div>
            ) : (
                <>
                    {/* Header */}
                    <div className="text-center mb-8">
                        <h1 className="text-4xl md:text-5xl font-serif font-bold text-gray-800 mb-2">
                            {isEditMode ? 'Edit Your Room Listing' : 'Create Your Room Listing'}
                        </h1>
                        <p className="text-gray-600 max-w-2xl mx-auto">
                            {isEditMode
                                ? 'Update your room details below. Changes may require re-approval.'
                                : 'Fill in the details below to create your room listing. All fields marked with * are required.'}
                        </p>
                    </div>

                    {/* Main Form Container */}
                    <div className="w-full max-w-full mx-auto px-4">
                        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border-4 border-[#e9d29f]">
                            {/* Cover Photo Section */}
                            <div className="bg-gradient-to-r from-green-50 to-sky-50 py-6 px-4 md:px-6 border-b border-gray-200">
                                <div className="flex flex-col md:flex-row gap-6 items-center">
                                    {/* Cover Photo */}
                                    <div className="w-full flex flex-col items-center">
                                        <div className="relative w-full h-72 md:h-96 bg-gray-100 rounded-2xl border-2 border-dashed border-gray-400 flex flex-col items-center justify-center overflow-hidden">
                                            {coverPhotoPreview ? (
                                                <>
                                                    <img
                                                        src={coverPhotoPreview}
                                                        alt="Cover Preview"
                                                        className="w-full h-full object-cover"
                                                    />
                                                    <Button
                                                        type="button"
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => {
                                                            setCoverPhoto(null);
                                                            setCoverPhotoPreview(null);
                                                        }}
                                                        className="absolute top-2 right-2 h-8 w-8 rounded-full bg-red-500 text-white hover:bg-red-600"
                                                    >
                                                        <FaTimes size={14} />
                                                    </Button>
                                                </>
                                            ) : (
                                                <>
                                                    <input
                                                        type="file"
                                                        id="coverPhoto"
                                                        className="sr-only"
                                                        onChange={handleCoverPhotoChange}
                                                        accept="image/*"
                                                        max="6"
                                                        required
                                                    />
                                                    <label
                                                        htmlFor="coverPhoto"
                                                        className="flex flex-col items-center justify-center w-full h-full cursor-pointer"
                                                    >
                                                        <FaPlus size={64} className="text-gray-400 mb-2" />
                                                        <p className="text-gray-600 font-medium">Add Cover Photo</p>
                                                        <p className="text-xs text-gray-500 mt-1">Recommended: 1200x800px</p>
                                                    </label>
                                                </>
                                            )}
                                        </div>
                                        <p className="text-xs text-gray-500 mt-2 text-center">
                                            This will be the main photo for your listing. Make sure it's well-lit and shows your room clearly.
                                        </p>
                                    </div>

                                    {/* Other Photos */}
                                    {/* Other Photos - Full width */}
                                    <div className="w-full">
                                        <div className="bg-white rounded-2xl border border-gray-200 p-4 flex flex-col">
                                            <div className="flex items-center justify-between mb-4">
                                                <h3 className="font-serif text-xl font-bold text-gray-800">Additional Photos</h3>
                                                <label
                                                    htmlFor="otherPhotos"
                                                    className="cursor-pointer transition-all bg-[#0a3d2e] text-white px-4 py-2 rounded-lg text-sm font-bold tracking-wide hover:brightness-110 hover:-translate-y-[1px] hover:border-b-[4px] active:border-b-[2px] active:brightness-90 active:translate-y-[1px] hover:shadow-xl hover:shadow-green-300/30 shadow-green-300/20 active:shadow-none border-b-[3px] border-[#33994c] flex items-center gap-1"
                                                >
                                                    <FaPlus size={14} /> Add Photos
                                                    <input
                                                        type="file"
                                                        id="otherPhotos"
                                                        className="sr-only"
                                                        multiple
                                                        onChange={handleOtherPhotosChange}
                                                        accept="image/*"
                                                    />
                                                </label>
                                            </div>

                                            {otherPhotosPreviews.length > 0 ? (
                                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 flex-1 min-h-[150px] overflow-y-auto pr-2">
                                                    {otherPhotosPreviews.map((url, index) => (
                                                        <div key={index} className="relative aspect-square rounded-lg overflow-hidden border border-gray-200">
                                                            <img
                                                                src={url}
                                                                alt={`Preview ${index}`}
                                                                className="w-full h-full object-cover"
                                                            />
                                                            <Button
                                                                type="button"
                                                                variant="ghost"
                                                                size="icon"
                                                                onClick={() => removeOtherPhoto(index)}
                                                                className="absolute top-1 right-1 h-6 w-6 rounded-full bg-red-500 text-white hover:bg-red-600"
                                                            >
                                                                <FaTimes size={12} />
                                                            </Button>
                                                        </div>
                                                    ))}
                                                </div>
                                            ) : (
                                                <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500">
                                                    <FaPlus size={32} className="mb-2 opacity-50" />
                                                    <p>Add photos of your room, bathroom, common areas, and amenities</p>
                                                </div>
                                            )}

                                            <p className="text-xs text-gray-500 mt-3">
                                                You can add up to 6 additional photos. Show your room from different angles!
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Form Content - Two Column Layout */}
                            <div className="p-4 md:p-6">
                                <form onSubmit={handleSubmit} className="space-y-6">
                                    {/* Two Column Layout */}
                                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                                        {/* Left Column - Room Details */}
                                        <div className="space-y-4">
                                            {/* Room Configuration */}
                                            <div className="space-y-4">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-green-100 text-green-800 rounded-full p-1">
                                                        <FaBed size={20} />
                                                    </span>
                                                    Room Configuration
                                                </h2>

                                                {/* Room Type Selection */}
                                                <div className="space-y-1">
                                                    <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                        Room Type <span className="text-red-500">*</span>
                                                    </label>
                                                    <Select onValueChange={setRoomType} value={roomType} required>
                                                        <SelectTrigger className="w-full border-2 focus:border-primary focus:ring-2 focus:ring-primary/20">
                                                            <SelectValue placeholder="Select room type" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="single">Single Occupancy</SelectItem>
                                                            <SelectItem value="double">Double Sharing</SelectItem>
                                                            <SelectItem value="triple">Triple Sharing</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                </div>

                                                {/* Gender Selection */}
                                                <div className="space-y-1">
                                                    <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                        Gender Preference <span className="text-red-500">*</span>
                                                    </label>
                                                    <Select onValueChange={setGender} value={gender} required>
                                                        <SelectTrigger className="w-full border-2 focus:border-primary focus:ring-2 focus:ring-primary/20">
                                                            <SelectValue placeholder="Select gender preference" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="any">Any Gender</SelectItem>
                                                            <SelectItem value="boys">Boys Only</SelectItem>
                                                            <SelectItem value="girls">Girls Only</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                </div>

                                                {/* Bathroom Type */}
                                                <div className="space-y-3 pt-2">
                                                    <label className="font-serif text-lg font-bold text-gray-800">
                                                        Bathroom Type
                                                    </label>
                                                    <div className="flex flex-wrap gap-3">
                                                        <CustomRadioToggle
                                                            label="Attached Bathroom"
                                                            isActive={bathroom === 'attached'}
                                                            onClick={() => setBathroom('attached')}
                                                            icon={FaShower}
                                                        />
                                                        <CustomRadioToggle
                                                            label="Shared Bathroom"
                                                            isActive={bathroom === 'shared'}
                                                            onClick={() => setBathroom('shared')}
                                                            icon={FaBath}
                                                        />
                                                    </div>
                                                </div>

                                                {/* Electricity Bill */}
                                                <div className="space-y-3 pt-2">
                                                    <label className="font-serif text-lg font-bold text-gray-800">
                                                        Electricity Bill
                                                    </label>
                                                    <div className="flex flex-wrap gap-3">
                                                        <CustomRadioToggle
                                                            label="Included in Rent"
                                                            isActive={lightBillIncluded}
                                                            onClick={() => setLightBillIncluded(true)}
                                                            icon={FaBolt}
                                                        />
                                                        <CustomRadioToggle
                                                            label="Not Included"
                                                            isActive={!lightBillIncluded}
                                                            onClick={() => setLightBillIncluded(false)}
                                                            icon={FaBolt}
                                                        />
                                                    </div>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Right Column - Basic Info & Facilities */}
                                        <div className="space-y-4">
                                            {/* Basic Information */}
                                            <div className="space-y-4">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-amber-100 text-amber-800 rounded-full p-1">
                                                        <FaInfoCircle size={20} />
                                                    </span>
                                                    Basic Information
                                                </h2>

                                                <div className="space-y-4">
                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                            Room Title <span className="text-red-500">*</span>
                                                        </label>
                                                        <Input
                                                            placeholder="e.g., Spacious AC Room near University"
                                                            value={title}
                                                            onChange={e => setTitle(e.target.value)}
                                                            required
                                                            className="border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                        />
                                                    </div>

                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                            Location Address <span className="text-red-500">*</span>
                                                        </label>
                                                        <Autocomplete
                                                            onLoad={(ref) => (searchBoxRef.current = ref)}
                                                            onPlaceChanged={handlePlaceSelect}
                                                            options={{
                                                                componentRestrictions: { country: 'in' },
                                                                fields: ['formatted_address', 'geometry', 'name'],
                                                            }}
                                                        >
                                                            <Input
                                                                placeholder="Search for your room address..."
                                                                value={address}
                                                                onChange={e => setAddress(e.target.value)}
                                                                required
                                                                className="border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                            />
                                                        </Autocomplete>
                                                        <p className="text-xs text-gray-500 mt-1">
                                                            Search your address, then drag the pin on the map below to the exact building location.
                                                        </p>
                                                    </div>

                                                    {/* Interactive Map with Draggable Pin */}
                                                    <div className="space-y-2">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-2">
                                                            <FaMapPin className="text-green-700" /> Pinpoint Location
                                                        </label>
                                                        <div className="relative w-full h-[300px] overflow-hidden rounded-xl border-2 border-gray-300 shadow-md">
                                                            {isLoaded && !loadError && !mapError ? (
                                                                <GoogleMap
                                                                    mapContainerStyle={{ width: '100%', height: '100%' }}
                                                                    center={location || mapCenter}
                                                                    zoom={location ? 16 : 12}
                                                                    onClick={handleMapClick}
                                                                    onLoad={handleMapLoad}
                                                                    onUnmount={() => setMapInstance(null)}
                                                                    onError={handleMapError}
                                                                    options={{
                                                                        streetViewControl: false,
                                                                        mapTypeControl: true,
                                                                        mapTypeControlOptions: {
                                                                            style: window.google?.maps?.MapTypeControlStyle?.DEFAULT,
                                                                            position: window.google?.maps?.ControlPosition?.TOP_RIGHT,
                                                                        },
                                                                        fullscreenControl: false,
                                                                        mapId: MAP_ID
                                                                    }}
                                                                >
                                                                    <AdvancedMarker
                                                                        position={location || mapCenter}
                                                                        map={mapInstance}
                                                                        draggable={true}
                                                                        onDragEnd={handleMarkerDragEnd}
                                                                        onMarkerError={handleMarkerError}
                                                                    />
                                                                </GoogleMap>
                                                            ) : (
                                                                <div className="w-full h-full bg-gray-100 border-2 border-dashed border-gray-300 rounded-xl flex flex-col items-center justify-center">
                                                                    <MapPin className="h-8 w-8 text-gray-400 mb-2" />
                                                                    <span className="text-gray-500 text-sm">Map preview unavailable</span>
                                                                </div>
                                                            )}
                                                        </div>
                                                        {location && (
                                                            <p className="text-xs text-gray-500 font-mono bg-gray-50 px-3 py-2 rounded-lg border border-gray-200">
                                                                📍 {location.lat.toFixed(6)}, {location.lng.toFixed(6)}
                                                            </p>
                                                        )}
                                                    </div>

                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                            Description <span className="text-red-500">*</span>
                                                        </label>
                                                        <Textarea
                                                            placeholder="Describe your room, amenities, rules, nearby places, etc."
                                                            value={description}
                                                            onChange={e => setDescription(e.target.value)}
                                                            className="min-h-[120px] border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                            required
                                                        />
                                                        <p className="text-xs text-gray-500">
                                                            Include details like room size, furniture, nearby landmarks, and any special rules.
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Pricing Section */}
                                            <div className="space-y-4 pt-6 border-t border-gray-200">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-rose-100 text-rose-800 rounded-full p-1">
                                                        <FaRupeeSign size={20} />
                                                    </span>
                                                    Pricing Details
                                                </h2>

                                                <div className="space-y-1">
                                                    <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-2">
                                                        <span>💰</span> Monthly Rent (₹)
                                                    </label>
                                                    <div className="relative">
                                                        <Input
                                                            type="number"
                                                            value={rent}
                                                            onChange={(e) => setRent(e.target.value)}
                                                            placeholder="8500"
                                                            className="pl-12 text-2xl font-bold text-gray-800 border-2 border-gray-300 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                            required
                                                        />
                                                        <span className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-lg">₹</span>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Facilities Section */}
                                            <div className="space-y-4 pt-6 border-t border-gray-200">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-green-100 text-green-800 rounded-full p-1">
                                                        <FaPlus size={20} />
                                                    </span>
                                                    Available Facilities
                                                </h2>

                                                <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                                    {FACILITY_OPTIONS.map(opt => {
                                                        const Icon = opt.icon;
                                                        return (
                                                            <div
                                                                key={opt.key}
                                                                onClick={() => handleFacilityToggle(opt.key)}
                                                                className={cn(
                                                                    "flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all cursor-pointer",
                                                                    selectedFacilities.includes(opt.key)
                                                                        ? "border-green-500 bg-green-50 text-green-700 shadow-md scale-[1.02]"
                                                                        : "border-gray-300 bg-white text-gray-700 hover:bg-gray-50"
                                                                )}
                                                            >
                                                                <div className={cn(
                                                                    "w-10 h-10 rounded-full flex items-center justify-center mb-2",
                                                                    selectedFacilities.includes(opt.key) ? "bg-green-100" : "bg-gray-100"
                                                                )}>
                                                                    <Icon size={20} />
                                                                </div>
                                                                <p className="text-xs font-medium text-center">{opt.name}</p>
                                                            </div>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Form Actions */}
                                    <div className="pt-6 border-t border-gray-200 flex flex-col sm:flex-row justify-between gap-4">
                                        <div className="flex gap-3">
                                            <Button
                                                type="button"
                                                variant="destructive"
                                                onClick={clearForm}
                                                className="bg-red-500 hover:bg-red-600 text-white font-semibold px-4 py-2"
                                            >
                                                Clear Form
                                            </Button>
                                        </div>
                                        <Button
                                            type="submit"
                                            className="bg-primary hover:bg-primary/90 font-bold text-lg px-8 py-3 shadow-lg"
                                            disabled={isLoading}
                                        >
                                            {isLoading ? 'Creating...' : 'Create Room Listing'}
                                        </Button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>

                    {/* Confirmation Modal */}
                    <Dialog open={isConfirmOpen} onOpenChange={setIsConfirmOpen}>
                        <DialogContent className="sm:max-w-md">
                            <DialogHeader>
                                <DialogTitle className="text-2xl font-serif font-bold text-gray-800">
                                    Confirm Room Listing
                                </DialogTitle>
                            </DialogHeader>

                            <div className="py-4 space-y-4">
                                <p className="text-gray-600">
                                    You're about to submit your room listing for approval. Please review the details below:
                                </p>

                                <div className="space-y-3 bg-gray-50 p-4 rounded-lg">
                                    <div className="flex justify-between">
                                        <span className="font-medium">Room Title:</span>
                                        <span>{title || 'Not provided'}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="font-medium">Room Type:</span>
                                        <span className="text-green-600 font-medium capitalize">{roomType}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="font-medium">Monthly Rent:</span>
                                        <span className="font-bold text-primary">₹{rent}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="font-medium">Facilities:</span>
                                        <span>{selectedFacilities.length} selected</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="font-medium">Photos:</span>
                                        <span>{1 + otherPhotos.length} photos</span>
                                    </div>
                                </div>

                                <div className="bg-amber-50 border-l-4 border-amber-400 p-3 rounded-r-lg">
                                    <p className="text-sm text-amber-800 font-medium">
                                        Note: Your listing will be reviewed by our team before going live. You'll receive an email notification once approved.
                                    </p>
                                </div>
                            </div>

                            <DialogFooter className="gap-3">
                                <Button
                                    variant="outline"
                                    onClick={() => setIsConfirmOpen(false)}
                                    className="border-gray-300 hover:bg-gray-50"
                                >
                                    Cancel
                                </Button>
                                <Button
                                    onClick={handleConfirmSubmit}
                                    className="bg-primary hover:bg-primary/90 min-w-[120px]"
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Submitting...' : isEditMode ? 'Update Room' : 'Confirm & Submit'}
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                </>
            )}
        </div>
    );
};

export default CreateRoomForm;